var t=[{title:`Concentrische actie`,text:`De spier levert kracht terwijl hij over het geheel korter wordt. Bij een bicepscurl worden de elleboogbuigers korter terwijl het gewicht omhooggaat. Op de weg omhoog uit een squat werken verschillende heup- en kniestrekkers om je op te tillen. „Concentrisch” beschrijft wat een spier doet, en dat is niet altijd hetzelfde als of de oefening eruitziet als een opwaartse beweging.`},{title:`Excentrische actie`,text:`De spier levert kracht terwijl hij onder belasting langer wordt, vaak om een beweging af te remmen. Een dumbbellcurl laten zakken of in een squat gaan zitten gebruikt excentrische actie van de belangrijkste werkende spieren. Deze fase helpt kracht en spiergroei, maar heel onbekend excentrisch werk kan veel spierpijn geven. Bouw het geleidelijk op en overdrijf niet elke daalfase met opzet.`},{title:`Isometrische actie`,text:`De spier levert kracht zonder veel verandering in zijn totale lengte of in de gewrichtshoek die hij controleert. Planks en wall sits zijn duidelijke voorbeelden, en je rompspieren werken ongeveer isometrisch als je een zware carry vasthoudt. Een houding op één hoek is geen perfecte vervanging voor bewegen door het hele bereik.`},{title:`Rollen veranderen met de taak`,text:`Een agonist is een hoofdbijdrager aan de beoogde actie, en een antagonist werkt tegen of helpt de beweging te regelen. Synergisten helpen, en stabilisatoren beheersen gewrichten of lichaamsdelen. Bij een push-up doen de borst en triceps het duwen terwijl de rompspieren je op één lijn houden. Deze rollen hangen af van de beweging, dus een spier heeft geen vast etiket.`},{title:`In de praktijk brengen`,text:`Laat gecontroleerd zakken, vermijd ongecontroleerd stuiteren en duw of trek door een bereik dat je kunt beheersen. Houdingen op tijd zijn handig als de taak geen beweging vraagt, en dynamische herhalingen zijn handig als je kracht door beweging wilt. In TrainUp staat elke oefening ingesteld op herhalingen of op een houdtijd, en de houdtimer houdt je houdingen bij. Techniekaanwijzingen en tempo helpen je goede herhalingen te doen, maar langzamer bewegen geeft niet altijd snellere resultaten.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Overzicht van mechanismen van spiergroei`,url:`https://pubmed.ncbi.nlm.nih.gov/37382939/`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};